"""Rotor hub stays on the aircraft at every heading/altitude; treated sprites and a saved stalled flight recover correctly."""
from playwright.sync_api import sync_playwright
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox']);page=b.new_page(viewport={'width':1440,'height':1100});errors=[];page.on('pageerror',lambda e:errors.append(e.stack))
 page.goto('http://127.0.0.1:8000',wait_until='networkidle');page.locator('#blackline-continue').click()
 page.evaluate("state.simClock.paused=true;['pmc-directions','pmc-casualties','helicopters'].forEach(n=>FieldArt.image('images/operators/'+n+'.webp'))")
 page.wait_for_function("['pmc-directions','pmc-casualties','helicopters'].every(n=>FieldArt.image('images/operators/'+n+'.webp').naturalWidth>0)")
 result=page.evaluate('''()=>{const c=document.createElement('canvas').getContext('2d'),draw=c.drawImage.bind(c),move=c.moveTo.bind(c);let body=null,hub=null;c.drawImage=(im,...a)=>{const m=c.getTransform();if(im.src.endsWith('helicopters.webp'))body=m.transformPoint({x:a[4]+472/768*a[6],y:a[5]+211/512*a[7]});draw(im,...a)};c.moveTo=(x,y)=>{if(hub===null)hub=c.getTransform().transformPoint({x,y});move(x,y)};const centers=[];for(const heading of [0,Math.PI/3,Math.PI])for(const altitude of [0,35]){body=null;hub=null;FieldArt.helicopter(c,150,160,heading,90,4,altitude);if(!body||!hub||Math.hypot(body.x-hub.x,body.y-hub.y)>.01)throw Error('detached rotor');centers.push({heading,altitude,x:hub.x,y:hub.y})}for(let i=0;i<centers.length;i+=2){if(Math.abs(centers[i].x-centers[i+1].x)>.01||Math.abs(centers[i].y-centers[i+1].y-4.2)>.01)throw Error('altitude moved body and rotor differently')}return centers.length}''')
 assert result==6
 page.evaluate('''()=>{const c=document.createElement('canvas').getContext('2d'),draw=c.drawImage.bind(c);let sources=[];c.drawImage=(im,...a)=>{sources.push(im.src.split('/').pop());draw(im,...a)};const u={faction:'blackline',name:'검증'},base=[0,0,45,30,'evacuated',0,0];function rendered(health){sources=[];FieldArt.unit(c,u,[...base,health],50,50,30,0,false,false);return sources.join(',')}if(!rendered({w:[['leftLeg',3,0,'총상']],f:false,d:false}).includes('pmc-casualties'))throw Error('untreated pose missing');if(rendered({w:[['leftLeg',3,1,'총상']],f:false,d:false})!=='pmc-directions.webp')throw Error('treated unit not restored');if(!rendered({w:[['leftLeg',3,1,'총상']],f:false,d:true}).includes('pmc-casualties'))throw Error('dead actor restored');if(rendered({w:[['leftLeg',3,1,'총상']],f:false,d:false,by:'carrier'}))throw Error('carried actor drawn twice');}''')
 page.evaluate('''()=>{const members=['팀장','의무','정찰','소총수','지원','저격수','소총수','소총수'].map((role,i)=>({id:101+i,name:'의료검증'+i,country:'대한민국',unit:'가상 부대',rank:'중사',role,skill:85,salary:60000000,birthDate:'1995-01-01',loadout:{primary:'M4A1'}}));state.team=members;const m={id:1,title:'의료 헬기 탑승 복원 검증',type:'시설 보안',risk:1,mapId:'urban',pinMap:true,objectiveMode:'guard'},op={id:'MEDICAL-FLIGHT-REPAIR',leaderName:members[0].name,budget:20000000,contract:m,status:'현장 진행 중',teamIds:members.map(p=>p.id),fieldProgress:{seed:25,supportOrders:[],staffingAudited:true}};state.operations=[op];const s=fieldSimulation.create(op,m,members,1600,{forceContact:false,medicalBudget:10,factions:[{id:'n',name:'중립',relation:80}]});op.fieldProgress.tactical=s;s.time=550;s.journey.stage='site';s.phase='수색';s.journey.drone={launched:true,finished:true};for(const [i,u]of s.units.filter(u=>u.faction==='blackline').entries()){u.inside=false;u.onRoof=false;u.x=50+i*.5;u.y=34;}const patient=s.units.find(u=>u.personId===103);fieldSimulation.applyWound(s,patient,80,null,'leftArm');fieldSimulation.performAid(s,patient,s.units[1]);patient.x=57;patient.y=34;s.journey.medevac={stage:'landed',scene:'site',patients:[patient.id],lz:[45,34],path:[s.terrain.base.slice(),[45,34]],distance:40,altitude:0,boarding:5,position:{x:45,y:34,heading:0},carriers:{},staged:[patient.id]};fieldSimulation.captureFrame(s);openFieldObservation(op.id);save()}''')
 page.reload(wait_until='networkidle');page.locator('#blackline-continue').click();page.evaluate("openFieldObservation('MEDICAL-FLIGHT-REPAIR')")
 page.evaluate('''()=>{const op=state.operations[0],s=op.fieldProgress.tactical,p=s.units.find(u=>u.personId===103);for(let i=0;i<500&&!s.journey.medevac.loadedIds?.includes(p.id);i++)fieldSimulation.step(s,op);if(!s.journey.medevac.loadedIds.includes(p.id))throw Error('patient never boarded');if(s.journey.medevac.stage!=='returning')throw Error('flight waiting after boarding')}''')
 page.wait_for_timeout(1300);page.screenshot(path='/tmp/blackline-v44-medical-takeoff.png',full_page=True)
 page.evaluate('''()=>{const op=state.operations[0],s=op.fieldProgress.tactical;for(let i=0;i<500&&s.journey.medevac.stage!=='complete';i++)fieldSimulation.step(s,op);if(s.journey.medevac.stage!=='complete')throw Error('flight did not finish');const p=s.units.find(u=>u.personId===103);if(p.status!=='evac-home'||!p.evacComplete)throw Error('hospital handover missing')}''')
 assert not errors,errors
 print('PASS rotor/body hub alignment at 6 transforms; treated normal sprite without healing or duplication; saved boarding stall completes flight and hospital handover')
 b.close()
